'use client'

import * as React from 'react'
import { ChartCard, ChartLegendPill, defaultFormat, type ChartCardBaseProps } from '@/registry/satin/ui/chart'
import { useSatinLabels } from '@/registry/satin/ui/labels'

/**
 * Donut chart, 1:1 with the uiKit `chart/donutCard` (4067:7096), in the shared ChartCard
 * (chart.tsx).
 *
 * A 184px ring (20px thick) of chart/1–5 segments starting at 12 o'clock, a 2px gap between
 * them, with the sum in the middle (text/xl semibold) over `centerLabel` in text/muted. The sum
 * lives in the ring, so the card's summary shows only the range. Under the ring a legend of
 * plain pills (swatch and label, the value is in the ring on hover) in two columns, 16 × 8 apart.
 * From 560px the legend moves to the right of the ring as one column.
 *
 * Hover a segment or its pill (or set `highlight`): the other segments fade to 15%, the other
 * pills' content to 45% (the hovered one fills bg/hover), and the middle shows the hovered value over "Label · 20%".
 */
export interface DonutCardProps extends Omit<ChartCardBaseProps, 'total' | 'change'> {
  /** Under the sum in the middle. Defaults to the `total` label. */
  centerLabel?: string
}

const SIZE = 184
const STROKE = 20
const R = (SIZE - STROKE) / 2
const C = 2 * Math.PI * R
const GAP = 2

// Written out whole, so the npm build can point each at its --sa-chart-* name.
const SERIES = ['var(--sa-chart-1)', 'var(--sa-chart-2)', 'var(--sa-chart-3)', 'var(--sa-chart-4)', 'var(--sa-chart-5)']
const seriesColor = (i: number) => SERIES[i % SERIES.length]

export function DonutCard({ data, formatValue = defaultFormat, highlight, centerLabel, ...props }: DonutCardProps) {
  const labels = useSatinLabels()
  const [hovered, setHovered] = React.useState<number | null>(null)
  const active = (hovered != null && hovered < data.length ? hovered : null) ?? highlight ?? null
  const sum = data.reduce((s, d) => s + Math.max(0, d.value), 0) || 1
  const share = (v: number) => Math.round((v / sum) * 100)

  let offset = 0
  const arcs = data.map((d, i) => {
    const len = (Math.max(0, d.value) / sum) * C
    const arc = { i, start: offset, len: Math.max(0, len - GAP) }
    offset += len
    return arc
  })

  return (
    <ChartCard {...props}>
      <div
        className="sa:flex sa:flex-col sa:items-center sa:gap-4 sa:@min-[560px]:flex-row sa:@min-[560px]:gap-8"
        onPointerLeave={() => setHovered(null)}
      >
        <div className="sa:relative sa:shrink-0 sa:py-2" style={{ width: SIZE }}>
          <svg width={SIZE} height={SIZE} viewBox={`0 0 ${SIZE} ${SIZE}`} aria-hidden className="sa:block sa:-rotate-90">
            {arcs.map(({ i, start, len }) => (
              <circle
                key={data[i].label}
                cx={SIZE / 2}
                cy={SIZE / 2}
                r={R}
                fill="none"
                stroke={seriesColor(i)}
                strokeWidth={STROKE}
                strokeDasharray={`${len} ${C - len}`}
                strokeDashoffset={-start}
                onPointerEnter={() => setHovered(i)}
                className="sa:transition-opacity sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)"
                style={{ opacity: active !== null && active !== i ? 0.15 : 1 }}
              />
            ))}
          </svg>
          <div aria-live="polite" className="sa:pointer-events-none sa:absolute sa:inset-0 sa:flex sa:flex-col sa:items-center sa:justify-center sa:text-center">
            <span className="sa:text-xl sa:leading-(--sa-text-xl--line-height) sa:font-semibold sa:text-text-default sa:tabular-nums">
              {formatValue(active != null ? data[active].value : sum)}
            </span>
            <span className="sa:text-sm sa:leading-(--sa-text-sm--line-height) sa:text-text-muted">
              {active != null ? `${data[active].label} · ${share(data[active].value)}%` : (centerLabel ?? labels.total)}
            </span>
          </div>
        </div>
        <ul
          className="sa:grid sa:w-full sa:grid-cols-2 sa:gap-x-4 sa:gap-y-2 sa:px-2 sa:@min-[560px]:flex sa:@min-[560px]:flex-1 sa:@min-[560px]:flex-col sa:@min-[560px]:gap-1 sa:@min-[560px]:px-0"
          aria-label={props.title}
        >
          {data.map((d, i) => (
            <li
              key={d.label}
              tabIndex={0}
              onPointerEnter={() => setHovered(i)}
              onFocus={() => setHovered(i)}
              onBlur={() => setHovered(null)}
              aria-label={`${d.label}: ${formatValue(d.value)}, ${share(d.value)}%`}
              className="sa:min-w-0 sa:rounded-pill sa:outline-none sa:focus-visible:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]"
            >
              <ChartLegendPill
                variant="plain"
                className="sa:flex sa:w-full"
                color={seriesColor(i)}
                label={d.label}
                active={active === i}
                dimmed={active !== null && active !== i}
              />
            </li>
          ))}
        </ul>
      </div>
    </ChartCard>
  )
}
